import{z as B,x as d,o as t,c as A,q as r,j as o,D as e,d as i,s as l,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"动态连通性","description":"","frontmatter":{"title":"动态连通性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dynamic-connectivity.md","filePath":"cs/dynamic-connectivity.md","lastUpdated":1791413859000}'),p={name:"cs/dynamic-connectivity.md"};function c(m,a,h,D,u,T){const n=d("Mermaid");return t(),A("div",null,[a[2]||(a[2]=r('<h1 id="动态连通性" tabindex="-1">动态连通性 <a class="header-anchor" href="#动态连通性" aria-label="Permalink to &quot;动态连通性&quot;">​</a></h1><div class="epigraph"><p>边插入、删除时维护「是否同连通块」：插入用并查集；删除要树分解或 Euler Tour，均摊近对数。</p><footer>—— 据 Holm, de Lichtenberg and Thorup, Poly-Logarithmic Deterministic Fully-Dynamic Algorithms for Connectivity, 2001；并查集见 CLRS 第 21 章整理</footer></div><p>上一课<a href="/cs/contraction-hierarchies">收缩层次</a>预处理静态最短路。本课图在变：无向连通性的充分动态（插边+删边）。主干<a href="/cs/union-find">并查集</a>只合并、不拆。缺口是删边后如何重连。不重写路径压缩。后课流式模型：图自己也看不完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>半动态：只有插入（并查集），或只有删除（离线可重构）。充分动态：交错插删。离线删边：按时间倒过来变成插入。在线删边：维护生成森林；删树边后在「替换边」候选里找，或分层：每层生成森林，删边到下一层找替换（Holm 等）。均摊 \\(O(\\log^2 n)\\) 量级。</p><p>缺口是替换边，不是再 DFS 全图——那是 \\(O(n)\\) 每次。</p><p><span class="marginnote">离线删边可以直译成「先看完剧本再演」：提前知道全部操作的顺序，把删边按时间倒过来处理就变成插边，并查集直接上阵。代价是必须等所有操作到齐才能作答；在线算法要来一个操作答一个，难得多——这正是 HDT 2001 论文值钱的地方。</span></p><h3 id="生成树不是-mst-动态" tabindex="-1">生成树不是 MST 动态 <a class="header-anchor" href="#生成树不是-mst-动态" aria-label="Permalink to &quot;生成树不是 MST 动态&quot;">​</a></h3><p>连通性不需要权。动态 MST 更难（权更新）。本课只 0-1 连通。2-边连通、动态平面性另论。</p><p><span class="marginnote">Holm–de Lichtenberg–Thorup 2001 确定性多对数。Euler Tour Tree 维护森林连通与子树。Sleator–Tarjan LCT 也可切边。后课图流：空间 \\(\\tilde O(n)\\)，森林刚够存。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入非树边：记为多余边。删非树边：直接丢。删树边：在覆盖该切分的非树边里找，或降层。查询 <code>find</code> 是否同一树根。</p>',12)),(t(),o(s,null,{default:e(()=>[l(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8F%92%E8%BE%B9%22%5D%20--%3E%20UF%5B%22%E5%B9%B6%E5%85%A5%E6%A3%AE%E6%9E%97%20%2F%20%E8%AE%B0%E5%A4%9A%E4%BD%99%22%5D%0A%20%20DEL%5B%22%E5%88%A0%E8%BE%B9%22%5D%20--%3E%20REP%5B%22%E6%89%BE%E6%9B%BF%E6%8D%A2%E8%BE%B9%EF%BC%9F%22%5D%0A%20%20REP%20--%3E%20F%5B%22%E6%9B%B4%E6%96%B0%E7%94%9F%E6%88%90%E6%A3%AE%E6%9E%97%22%5D%0A%20%20F%20--%3E%20Q%5B%22%E5%90%8C%E5%9D%97%E6%9F%A5%E8%AF%A2%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"离线：时间倒流 + 并查集最简单。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"生成森林可以类比城市主干道网：树边是主干道，非树边是备用的立交桥。拆一条主干道（删树边）时，要紧的不是重建全城，而是看有没有一座立交桥恰好跨过断口——有就把它升格为临时主干道，没有则两片城区就此隔开，之后的连通查询按两片分别作答。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"切分 \\((A,B)\\) 的替换边即跨 \\(A\\)、\\(B\\) 的剩余边。分层把边按「被当作树边的级别」限制扫描范围，均摊对数层。与点分治：这里动态，切的是边生命周期。不要用 CH 捷边当动态连通：对象是最短路不是 0-1。",-1)),(t(),o(s,null,{default:e(()=>[l(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20TE%5B%22%E5%88%A0%E9%99%A4%E4%B8%80%E6%9D%A1%E6%A0%91%E8%BE%B9%22%5D%20--%3E%20CUT%5B%22%E6%A3%AE%E6%9E%97%E8%A2%AB%E5%88%87%E6%88%90%E4%B8%A4%E5%9D%97%EF%BC%9AA%20%E4%B8%8E%20B%22%5D%0A%20%20CUT%20--%3E%20SR%5B%22%E5%9C%A8%E9%9D%9E%E6%A0%91%E8%BE%B9%E9%87%8C%E6%89%BE%E8%B7%A8%E5%88%87%E5%88%86%E7%9A%84%E6%9B%BF%E6%8D%A2%E8%BE%B9%22%5D%0A%20%20SR%20--%3E%20F1%5B%22%E6%89%BE%E5%88%B0%EF%BC%9A%E5%8D%87%E6%A0%BC%E4%B8%BA%E6%96%B0%E6%A0%91%E8%BE%B9%EF%BC%8C%E6%A3%AE%E6%9E%97%E9%87%8D%E6%96%B0%E8%BF%9E%E9%80%9A%22%5D%0A%20%20SR%20--%3E%20F2%5B%22%E6%89%BE%E4%B8%8D%E5%88%B0%EF%BC%9AA%E3%80%81B%20%E4%BB%8E%E6%AD%A4%E4%B8%8D%E8%BF%9E%E9%80%9A%EF%BC%8C%E6%9F%A5%E8%AF%A2%E6%8C%89%E4%B8%A4%E6%A3%B5%E6%A0%91%E4%BD%9C%E7%AD%94%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">初学者容易想到「删一条边就重新 DFS 一遍判连通」。没错，但太贵：百万个点配百万次操作，每次 \\(O(n)\\) 的全图扫描就是天文数字；替换边思路把重扫限制在被切开的那一小片附近，均摊下来才是正文说的多对数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写最优单元代价下界全文（有条件下界）。有向图动态强连通更难。后课默认：插边并查集；充分动态用分层森林或 LCT。下一课图流与半流：内存读一遍。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>插入易、删除要替换边或离线倒流。</li><li>充分动态可达多对数均摊。</li><li>只问连通，不是动态最短路。</li><li>出处：Holm, de Lichtenberg and Thorup, 2001；CLRS 并查集。</li></ul>',5))])}const F=B(p,[["render",c]]);export{f as __pageData,F as default};
